// TestChooseReleaseMatchesPython replays testdata/choose_python.json,
// generated by gen_golden.py from Python's versions.choose.
func TestChooseReleaseMatchesPython(t *testing.T) {
	raw, err := os.ReadFile("../../testdata/choose_python.json")
	if err != nil {
		t.Fatal(err)
	}
	var data struct {
		Releases map[string][]string `json:"releases"`
		Cases    []struct {
			Releases, Constraint, Preferred, Version, Basis, Error string
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &data); err != nil {
		t.Fatal(err)
	}
	for _, c := range data.Cases {
		releases := releasesOf(data.Releases[c.Releases], c.Releases == "tags")
		got, basis, err := chooseRelease(releases, c.Constraint, c.Preferred)
		gotErr := ""
		if err != nil {
			gotErr = err.Error()
		}
		if got.version != c.Version || basis != c.Basis || gotErr != c.Error {
			t.Errorf("%s %q preferred=%q: got (%q, %q, %q), Python (%q, %q, %q)", c.Releases, c.Constraint,
				c.Preferred, got.version, basis, gotErr, c.Version, c.Basis, c.Error)
		}
	}
}

// fakeRegistry serves bodies keyed by URL-path substring; anything else 404s.
func fakeRegistry(t *testing.T, routes map[string]string) (registryClient, *[]string) {
	t.Helper()
	var urls []string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		urls = append(urls, r.URL.RequestURI())
		for part, body := range routes {
			if strings.Contains(r.URL.RequestURI(), part) {
				_, _ = w.Write([]byte(body))
				return
			}
		}
		http.NotFound(w, r)
	}))
	t.Cleanup(server.Close)
	base := map[string]string{}
	for eco := range DefaultRegistryURLs {
		base[eco] = server.URL
	}
	return registryClient{http: server.Client(), urls: base}, &urls
}

func versionsOf(rs []release) []string {
	var out []string
	for _, r := range rs {
		out = append(out, r.version)
	}
	return out
}

func TestRegistriesSkipYankedAndEscapeNames(t *testing.T) {
	ctx := context.Background()
	c, urls := fakeRegistry(t, map[string]string{
		"/pypi/demo/json":     `{"releases": {"1.0.0": [{"yanked": false}], "1.1.0": [{"yanked": true}], "1.2.0": []}}`,
		"/api/v1/crates/demo": `{"versions": [{"num": "1.0.0"}, {"num": "1.1.0", "yanked": true}]}`,
		"/!azure/sdk/@v/list": "v1.2.0\nv1.3.0\n",
		"/repos/github/codeql-action/git/matching-refs/tags": `[{"ref": "refs/tags/v2.1.0"}, {"ref": "refs/tags/v2"}]`,
	})
	if rs, _, err := c.pypi(ctx, "demo"); err != nil || strings.Join(versionsOf(rs), ",") != "1.0.0" {
		t.Errorf("pypi = %v, %v", versionsOf(rs), err)
	}
	if rs, _, err := c.crates(ctx, "demo"); err != nil || strings.Join(versionsOf(rs), ",") != "1.0.0" {
		t.Errorf("crates = %v, %v", versionsOf(rs), err)
	}
	if rs, _, err := c.goProxy(ctx, "github.com/Azure/sdk"); err != nil || strings.Join(versionsOf(rs), ",") != "1.2.0,1.3.0" {
		t.Errorf("go = %v, %v (%v)", versionsOf(rs), err, *urls)
	}
	rs, _, err := c.githubActions(ctx, "github/codeql-action/init")
	if err != nil {
		t.Fatal(err)
	}
	if got, _, _ := chooseRelease(rs, "2.*.*", ""); got.version != "2.1.0" {
		t.Errorf("action subpath chose %q", got.version)
	}
}

func TestOversizedRegistryResponseIsAResolutionError(t *testing.T) {
	saved := maxRegistryBytes
	maxRegistryBytes = 10
	t.Cleanup(func() { maxRegistryBytes = saved })
	c, _ := fakeRegistry(t, map[string]string{"/pypi/demo/json": `{"releases": {"1.0.0": [{}]}}`})
	_, _, err := c.pypi(context.Background(), "demo")
	if _, ok := err.(resolutionError); !ok {
		t.Fatalf("err = %v", err)
	}
}

func TestResolveKeepsFailuresPerComponent(t *testing.T) {
	c, _ := fakeRegistry(t, nil)
	results, errs := resolveVersions(context.Background(), []resolveRequest{
		{0, "PyPI", "demo", ""}, {1, "npm", "demo", "release/v1"},
	}, c)
	if results[0].version != "" || results[1].version != "" || len(errs) != 2 {
		t.Fatalf("results %+v errs %v", results, errs)
	}
	if !strings.Contains(errs[0], "PyPI lookup failed") || !strings.Contains(errs[1], "not a version range") {
		t.Errorf("errs = %v", errs)
	}
}

// TestDeclaredConstraintsMatchPython replays testdata/manifests_python.json,
// generated by gen_golden.py from Python's declared_constraints.
func TestDeclaredConstraintsMatchPython(t *testing.T) {
	raw, err := os.ReadFile("../../testdata/manifests_python.json")
	if err != nil {
		t.Fatal(err)
	}
	var data struct {
		Manifests    map[string]string `json:"manifests"`
		Constraints  [][]any           `json:"constraints"`
		WarningPaths []string          `json:"warning_paths"`
		IsManifest   map[string]bool   `json:"is_manifest"`
	}
	if err := json.Unmarshal(raw, &data); err != nil {
		t.Fatal(err)
	}
	got, warnings := DeclaredConstraints(data.Manifests)
	want := map[RegistryKey]Declared{}
	for _, c := range data.Constraints {
		var paths []string
		for _, p := range c[3].([]any) {
			paths = append(paths, p.(string))
		}
		want[RegistryKey{c[0].(string), c[1].(string)}] = Declared{c[2].(string), paths}
	}
	for key, w := range want {
		if g, ok := got[key]; !ok || g.Constraint != w.Constraint || strings.Join(g.Paths, ",") != strings.Join(w.Paths, ",") {
			t.Errorf("%v: got %+v, Python %+v", key, g, w)
		}
	}
	for key := range got {
		if _, ok := want[key]; !ok {
			t.Errorf("%v: not declared in Python", key)
		}
	}
	var warned []string
	for _, w := range warnings {
		warned = append(warned, strings.SplitN(w, " could not be parsed", 2)[0])
	}
	if strings.Join(warned, ",") != strings.Join(data.WarningPaths, ",") {
		t.Errorf("warnings = %v, Python warned for %v", warnings, data.WarningPaths)
	}
	for path, want := range data.IsManifest {
		if IsManifest(path) != want {
			t.Errorf("IsManifest(%q) = %v", path, !want)
		}
	}
}
